import Foundation
import Testing
@testable import LayerCore

// MARK: - Fixtures (generated by Fixtures/make_fixtures.py from the Python that draws the printed keymaps)

struct CorneFixture: Decodable {
    struct K: Decodable { var x, y, w, h, r, rx, ry: Double; var row, col: Int }
    var keys: [K]
    var keymap: [[[UInt16]]]
    var labels: [[[[String]]]]

    static let shared: CorneFixture = {
        let url = Bundle.module.url(forResource: "Fixtures/corne-v4", withExtension: "json")!
        return try! JSONDecoder().decode(CorneFixture.self, from: Data(contentsOf: url))
    }()

    var keymapValue: Keymap {
        Keymap(layers: keymap.map { $0.flatMap { $0 } }, rows: keymap[0].count, cols: keymap[0][0].count)
    }
}

func corne() -> BoardProfile {
    BoardProfile.bundled().first { $0.id == "corne-v4" }!
}

func consoleBytes(_ text: String) -> [[UInt8]] {
    let b = Array(text.utf8)
    return stride(from: 0, to: b.count, by: 32).map { VIA.pad(Array(b[$0..<min($0 + 32, b.count)])) }
}

// MARK: - Console

@Suite struct ConsoleTests {
    @Test func parsesLayerLine() {
        #expect(LayerEvent(line: "LAYER 2 00000006") == LayerEvent(highest: 2, state: 6))
        #expect(LayerEvent(line: "LAYER 0 00000000") == LayerEvent(highest: 0, state: 0))
    }

    @Test(arguments: ["", "LAYER", "LAYER x 00000002", "LAYER 1", "hello world", "LAYER 1 zz", "LAYER 1 2 3"])
    func ignoresOtherLines(_ line: String) {
        #expect(LayerEvent(line: line) == nil)
    }

    @Test func splitsLinesAcrossPaddedReports() {
        var r = ConsoleLineReader()
        let reports = consoleBytes("LAYER 1 00000002\nLAYER 2 00000006\nLAY") + consoleBytes("ER 0 00000000\n")
        let lines = reports.flatMap { r.feed($0) }
        #expect(lines == ["LAYER 1 00000002", "LAYER 2 00000006", "LAYER 0 00000000"])
    }

    @Test func capsRunawayLines() {
        var r = ConsoleLineReader()
        for _ in 0..<40 { _ = r.feed(Array(repeating: 0x41, count: 32)) }
        let lines = r.feed(Array("\n".utf8))
        #expect(lines.first?.count == ConsoleLineReader.maxLine)
    }
}

// MARK: - Hold timer

@Suite struct HoldTimerTests {
    @Test func justUnderTheDelayShowsNothing() {
        var t = HoldTimer(delay: 3)
        #expect(t.layerChanged(1, at: 10) == nil)
        #expect(t.nextDeadline == 13)
        #expect(t.tick(at: 12.9) == nil)
    }

    @Test func atTheDelayShowsOnce() {
        var t = HoldTimer(delay: 3)
        _ = t.layerChanged(1, at: 10)
        #expect(t.tick(at: 13.0) == .show(1))
        #expect(t.tick(at: 14) == nil)
        #expect(t.nextDeadline == nil)
    }

    @Test func releaseBeforeTheDelayNeverShows() {
        var t = HoldTimer(delay: 3)
        _ = t.layerChanged(1, at: 10)
        #expect(t.layerChanged(0, at: 12) == nil)
        #expect(t.tick(at: 20) == nil)
    }

    @Test func releaseHides() {
        var t = HoldTimer(delay: 3)
        _ = t.layerChanged(1, at: 0)
        _ = t.tick(at: 3)
        #expect(t.layerChanged(0, at: 4) == .hide)
    }

    @Test func switchingBeforeShownRestartsTheWait() {
        var t = HoldTimer(delay: 3)
        _ = t.layerChanged(1, at: 0)
        _ = t.layerChanged(2, at: 2)
        #expect(t.tick(at: 3) == nil)
        #expect(t.tick(at: 5) == .show(2))
    }

    @Test func switchingWhileShownSwapsAtOnce() {
        var t = HoldTimer(delay: 3)
        _ = t.layerChanged(1, at: 0)
        _ = t.tick(at: 3)
        #expect(t.layerChanged(2, at: 4) == .show(2))
        #expect(t.layerChanged(1, at: 5) == .show(1))
    }

    @Test func repeatedReportOfTheSameLayerKeepsTheClock() {
        var t = HoldTimer(delay: 3)
        _ = t.layerChanged(1, at: 0)
        _ = t.layerChanged(1, at: 2)
        #expect(t.tick(at: 3) == .show(1))
    }

    @Test func delayIsConfigurable() {
        var t = HoldTimer(delay: 1)
        _ = t.layerChanged(1, at: 0)
        #expect(t.tick(at: 1) == .show(1))
    }
}

// MARK: - VIA

@Suite struct VIATests {
    @Test func chunksCoverTheWholeBuffer() {
        let c = VIA.chunks(total: 672)
        #expect(c.count == 24)
        #expect(c.map(\.size).reduce(0, +) == 672)
        #expect(c.last! == (644, 28))
        #expect(VIA.chunks(total: 30).map(\.size) == [28, 2])
    }

    @Test func buildsBufferRequests() {
        #expect(Array(VIA.getBuffer(offset: 0x1C0, size: 28).prefix(4)) == [0x12, 0x01, 0xC0, 28])
        #expect(VIA.getBuffer(offset: 0, size: 1).count == 32)
    }

    @Test func matchesRepliesToRequests() {
        let req = VIA.getBuffer(offset: 28, size: 28)
        #expect(VIA.isReply(Array(req.prefix(4)) + Array(repeating: 9, count: 28), to: req))
        #expect(!VIA.isReply(VIA.getBuffer(offset: 56, size: 28), to: req))
        #expect(!VIA.isReply(VIA.layerCount(), to: req))
    }

    /// A pretend board answering 0x11 and 0x12 from the real Corne readback.
    @Test func readsTheKeymapThroughAFakeBoard() throws {
        let fx = CorneFixture.shared, km = fx.keymapValue
        let flat = km.layers.flatMap { $0 }.flatMap { [UInt8($0 >> 8), UInt8($0 & 0xFF)] }
        var sent = 0
        let read = try KeymapReader.read(rows: 8, cols: 7) { req in
            sent += 1
            switch req[0] {
            case 0x11: return VIA.pad([0x11, UInt8(km.layers.count)])
            case 0x12:
                let off = Int(req[1]) << 8 | Int(req[2]), n = Int(req[3])
                return VIA.pad(Array(req.prefix(4)) + Array(flat[off..<(off + n)]))
            default: return nil
            }
        }
        #expect(read == km)
        #expect(sent == 1 + 24)
    }

    @Test func timeoutIsAnError() {
        #expect(throws: KeymapReader.ReadError.noReply(command: 0x11)) {
            try KeymapReader.read(rows: 8, cols: 7) { _ in nil }
        }
    }
}

// MARK: - Labels: must agree with gen_print.py on every key of the real keymap

@Suite struct LabelTests {
    @Test func agreesWithThePrintedKeymapOnEveryKey() {
        let fx = CorneFixture.shared, lab = corne().labeler
        var checked = 0
        for (l, layer) in fx.keymap.enumerated() {
            for (r, row) in layer.enumerated() {
                for (c, code) in row.enumerated() {
                    let py = fx.labels[l][r][c]
                    if py[1].hasSuffix("?") { continue }   // Python has no name for layers 4 and 5
                    let sw = lab.legend(code)
                    #expect([sw.main, sw.hold, sw.kind.rawValue] == py, "layer \(l) row \(r) col \(c) code \(String(code, radix: 16))")
                    checked += 1
                }
            }
        }
        #expect(checked > 300)
    }

    @Test(arguments: [
        (UInt16(0x422a), "Bksp", "hold Fn"),       // LT(Fn, Bksp): the second Space
        (UInt16(0x412c), "Space", "hold Nav"),     // LT(Nav, Space)
        (UInt16(0x2f0a), "G", "hold Hyper"),       // MT(Hyper, G)
        (UInt16(0x5222), "Fn", "hold"),            // MO(Fn)
        (UInt16(0x021e), "!", ""),                 // S(1)
        (UInt16(0x7700), "⌘ ⌘", "taps twice"),     // macro 0
    ])
    func labelsCommonKeycodes(code: UInt16, main: String, hold: String) {
        let l = corne().labeler.legend(code)
        #expect(l.main == main && l.hold == hold)
    }

    @Test func findsTheLayerAKeyTurnsOn() {
        #expect(KeyLabeler.targetLayer(0x412c) == 1)
        #expect(KeyLabeler.targetLayer(0x5222) == 2)
        #expect(KeyLabeler.targetLayer(0x5262) == 2)
        #expect(KeyLabeler.targetLayer(0x002c) == nil)
    }
}

// MARK: - Layout: must agree with gen_print.py's key positions

@Suite struct LayoutTests {
    @Test func corneLayoutMatchesThePrintedKeymap() {
        let fx = CorneFixture.shared, keys = corne().layout.keys
        #expect(keys.count == 46)
        #expect(keys.count == fx.keys.count)
        for (a, b) in zip(keys, fx.keys) {
            #expect(a.row == b.row && a.col == b.col)
            for (p, q) in [(a.x, b.x), (a.y, b.y), (a.w, b.w), (a.h, b.h), (a.r, b.r), (a.rx, b.rx), (a.ry, b.ry)] {
                #expect(abs(p - q) < 1e-9, "key \(b.row),\(b.col)")
            }
        }
    }

    @Test func profileLoads() {
        let p = corne()
        #expect(p.vendorId == 0x4653 && p.productId == 0x0004)
        #expect(p.layout.rows == 8 && p.layout.cols == 7)
        #expect(p.labeler.layerName(1) == "Nav")
    }
}

// MARK: - Controller, end to end: console bytes in, overlay out

final class FakePresenter: OverlayPresenting {
    var shown: [OverlayContent] = []
    var hides = 0
    func show(_ c: OverlayContent) { shown.append(c) }
    func hide() { hides += 1 }
}

@Suite struct ControllerTests {
    func make(delay: Double = 3) -> (OverlayController, FakePresenter) {
        let c = OverlayController(profile: corne(), delay: delay)
        let p = FakePresenter()
        c.presenter = p
        c.keymap = CorneFixture.shared.keymapValue
        return (c, p)
    }
    func send(_ c: OverlayController, _ text: String, at t: Double) {
        for r in consoleBytes(text) { c.consoleReport(r, at: t) }
    }

    @Test func holdingNavThreeSecondsShowsTheNavKeys() throws {
        let (c, p) = make()
        send(c, "LAYER 1 00000002\n", at: 100)
        c.tick(at: 102.9)
        #expect(p.shown.isEmpty)
        #expect(c.nextDeadline == 103)
        c.tick(at: 103)
        let shown = try #require(p.shown.first)
        #expect(shown.layerName == "Nav")
        // Nav: the left Space thumb is held; W is ↑ with W as its ghost.
        let w = try #require(shown.caps.first { $0.place.row == 0 && $0.place.col == 2 })
        #expect(w.main == "↑" && w.ghost == "W")
        let spaces = shown.caps.filter { $0.style == .held }
        #expect(spaces.count == 2)   // both Space thumbs turn Nav on
        send(c, "LAYER 0 00000000\n", at: 104)
        #expect(p.hides == 1)
    }

    @Test func stackingFnOnNavSwapsTheOverlay() {
        let (c, p) = make()
        send(c, "LAYER 1 00000002\n", at: 0)
        c.tick(at: 3)
        send(c, "LAYER 2 00000006\n", at: 4)
        #expect(p.shown.map(\.layerName) == ["Nav", "Fn"])
        // On Fn the keys that turned it on are the Bksp/hold-Fn thumbs on Nav and the Enter thumb on base.
        #expect(p.shown[1].caps.filter { $0.style == .held }.count >= 2)
    }

    @Test func ghostsCanBeTurnedOff() {
        let (c, p) = make()
        c.ghosts = false
        send(c, "LAYER 1 00000002\n", at: 0)
        c.tick(at: 3)
        #expect(p.shown.first?.caps.allSatisfy { $0.ghost.isEmpty } == true)
    }

    @Test func otherConsoleOutputIsIgnored() {
        let (c, p) = make(delay: 1)
        send(c, "debug: hello\nLAYER 1 00000002\nkeycode 0x2c\n", at: 0)
        c.tick(at: 1)
        #expect(p.shown.count == 1)
    }

    @Test func noKeymapYetShowsNothing() {
        let c = OverlayController(profile: corne(), delay: 1)
        let p = FakePresenter()
        c.presenter = p
        send(c, "LAYER 1 00000002\n", at: 0)
        c.tick(at: 1)
        #expect(p.shown.isEmpty)
        c.keymap = CorneFixture.shared.keymapValue   // arrives late: shows straight away
        #expect(p.shown.count == 1)
    }

    @Test func unplugHides() {
        let (c, p) = make(delay: 1)
        send(c, "LAYER 1 00000002\n", at: 0)
        c.tick(at: 1)
        c.reset()
        #expect(p.hides == 1)
    }
}
